#[test]
fn content_context_matches_controller_hash_vectors_including_platform_facts_and_number_strings() {
    // Generated by the actual plugins/sales-agent/src/content/context.ts helper.
    let mut product = json!({
        "id":"00000000-0000-4000-8000-000000000001","revision":2,"name":"Fixture product",
        "title":"Used cotton shirt","description":"A used cotton shirt.","price":12.0,
        "currency":"USD","category":"","condition":"Good","brand":"","size":"","tags":[],
        "platformFacts":{"vinted":[{"platformOrigin":"https://www.vinted.com","catalogId":10,
            "catalogRevision":"a".repeat(64),"attributes":{"10":"ten","2":"two","\u{e000}":"private","\u{1f600}":"face"}}]},
        "images":[{"id":"00000000-0000-4000-8000-000000000002",
            "artifactId":"00000000-0000-4000-8000-000000000003","name":"fixture.png",
            "mime":"image/png","bytes":8,"sha256":"a".repeat(64)}]
    });
    for (price, source, key) in [
        (
            12.0,
            "5fa4184163a804df688434186b163893d6e1fb506428a5977e322f2fbc09c1d1",
            "3037b6838c0e4eb439ee4c1118b8c3231a96df26cc845dc33e6dd8e7617e8912",
        ),
        (
            0.000001,
            "184e866e0a837c4052e64fc73641b790bb7adeb4f19dd7fcaf267dc773a15da9",
            "f51b6d0126800be79a3ab7872c178a8ac7f36f663678c6a61561cce1778318d0",
        ),
        (
            0.0000001,
            "e302ebd7256a51cfa4e2cfcc835f71954ae06b9447181ca8620d8e5f9473dd92",
            "4ebee043939f11692627f307a474d64c89fb550e4b09475dbfb0d60544d29cf0",
        ),
    ] {
        product["price"] = json!(price);
        let ctx = crate::core::agent::content::context(
            &product,
            &settings(),
            "https://www.vinted.com",
            "Use the supplied facts.",
        )
        .unwrap();
        assert_eq!(ctx["sourceDigest"], source);
        assert_eq!(
            ctx["modelDigest"],
            "e21ebd216beff40bb7d41bc4229786b397175ae088370f6ef1b6ddd4ebc940b2"
        );
        assert_eq!(ctx["contentKey"], key);
    }
}

#[test]
fn platform_facts_are_frozen_strict_and_invalidate_cached_content() {
    let (_temp, store) = fixture();
    let mut snap = snapshot();
    let mut source = product();
    source["platformFacts"] = json!({"vinted":[{"platformOrigin":"https://www.vinted.com",
        "catalogId":10,"catalogRevision":null,"attributes":{"Material":"Cotton"}}]});
    snap.products = vec![source.clone()];
    let (_, id) = raw_listing(&store, snap);
    let job = store.claim(&id, "fixture-generation").unwrap().unwrap();
    let effective = store.step_snapshot(&job).unwrap();
    assert_eq!(
        effective.products[0]["platformFacts"],
        source["platformFacts"]
    );
    let (key, p) = package(&store, &job, 0, "approved");
    let mut bad = p.clone();
    bad["product"]["platformFacts"]["vinted"][0]["attributes"]["Material"] = json!("Silk");
    assert!(
        store
            .content_put(
                job.scope.as_ref().unwrap(),
                "fixture-generation",
                p["productId"].as_str().unwrap(),
                &key,
                &bad
            )
            .is_err()
    );
    let mut changed = source.clone();
    changed["platformFacts"] = json!({"vinted":[]});
    assert_ne!(
        crate::core::agent::content::context(&source, &settings(), "https://www.vinted.com", "")
            .unwrap(),
        crate::core::agent::content::context(&changed, &settings(), "https://www.vinted.com", "")
            .unwrap()
    );
    for facts in [
        Value::Null,
        json!({"vinted":[{"platformOrigin":"https://www.vinted.com/","catalogId":null,"catalogRevision":null,"attributes":{}}]}),
        json!({"vinted":[{"platformOrigin":"https://www.vinted.com","catalogId":null,"catalogRevision":"a".repeat(64),"attributes":{}}]}),
        json!({"vinted":[{"platformOrigin":"https://www.vinted.com","catalogId":null,"catalogRevision":null,"attributes":{" Material":"Cotton"}}]}),
    ] {
        changed["platformFacts"] = facts;
        assert!(crate::core::agent::content::project_product(&changed).is_err());
    }
}

#[test]
fn cache_context_tracks_content_and_review_rules_but_excludes_locations_and_secrets() {
    let product = product();
    let settings = settings();
    let context = |p: &Value, s: &Value, origin: &str, instruction: &str| {
        crate::core::agent::content::context(p, s, origin, instruction).unwrap()
    };
    let baseline = context(&product, &settings, "https://www.vinted.com", "");
    for field in [
        "id",
        "revision",
        "title",
        "description",
        "condition",
        "price",
        "platformFacts",
        "images",
    ] {
        let mut changed = product.clone();
        changed[field] = match field {
            "id" => json!(fresh()),
            "revision" => json!(3),
            "price" => json!(13.0),
            "images" => {
                let mut images = changed["images"].clone();
                images[0]["sha256"] = json!("b".repeat(64));
                images
            }
            "platformFacts" => json!({"vinted":[{"platformOrigin":"https://www.vinted.com",
                "catalogId":10,"catalogRevision":null,"attributes":{}}]}),
            _ => json!("Changed fact"),
        };
        assert_ne!(
            context(&changed, &settings, "https://www.vinted.com", "")["contentKey"],
            baseline["contentKey"],
            "{field}"
        );
    }
    let mut located = product.clone();
    located["images"][0]["artifactId"] = json!(fresh());
    assert_eq!(
        context(&located, &settings, "https://www.vinted.com", ""),
        baseline
    );
    for field in ["apiKey", "requestTimeoutMs", "notifications"] {
        let mut changed = settings.clone();
        if field == "apiKey" {
            changed["decision"]["apiKey"] = json!("rotated");
        } else {
            changed[field] = json!(1234);
        }
        assert_eq!(
            context(&product, &changed, "https://www.vinted.com", ""),
            baseline
        );
    }
    let mut changed = settings.clone();
    changed["reviewThreshold"] = json!(0.9);
    assert_ne!(
        context(&product, &changed, "https://www.vinted.com", ""),
        baseline
    );
    changed = settings.clone();
    changed["decision"]["protocol"] = json!("openai");
    assert_ne!(
        context(&product, &changed, "https://www.vinted.com", ""),
        baseline
    );
    assert_ne!(
        context(&product, &settings, "https://www.vinted.fr", ""),
        baseline
    );
    assert_ne!(
        context(
            &product,
            &settings,
            "https://www.vinted.com",
            "Different review instruction"
        ),
        baseline
    );
}

fn raw_listing(store: &AgentStore, mut snap: JobSnapshot) -> (String, String) {
    if snap.products.is_empty() {
        snap.products.push(product());
    }
    let batch = fresh();
    let job = fresh();
    store
        .create(
            &batch,
            &input(&snap, Preset::PostListing),
            &[(job.clone(), snap)],
            &settings(),
        )
        .unwrap();
    (batch, job)
}

fn package(store: &AgentStore, job: &Job, index: usize, state: &str) -> (String, Value) {
    let snapshot = store.step_snapshot(job).unwrap();
    let mut source = snapshot.products[index].clone();
    let ctx = source
        .as_object_mut()
        .unwrap()
        .remove("preparationInput")
        .unwrap();
    (
        ctx["contentKey"].as_str().unwrap().into(),
        json!({
            "version":1,"state":state,"reason":"","productId":source["id"],"productRevision":source["revision"],
            "sourceDigest":ctx["sourceDigest"],"modelDigest":ctx["modelDigest"],
            "rulesVersion":"vinted-listing-v2","platformOrigin":job.snapshot.platform_origin,
            "product":if state=="approved" {source}else{Value::Null},"fallback":null,
            "reviewedAt":"2026-11-13T01:00:00.000Z"
        }),
    )
}

fn put(store: &AgentStore, job: &Job, index: usize, state: &str) -> (String, Value) {
    let (key, p) = package(store, job, index, state);
    assert_eq!(
        store
            .content_put(
                job.scope.as_ref().unwrap(),
                "fixture-generation",
                job.snapshot.products[index]["id"].as_str().unwrap(),
                &key,
                &p
            )
            .unwrap(),
        json!({"stored":true,"storageDurable":true})
    );
    (key, p)
}

// Existing journal/resource tests enter browser execution through real preparation.
pub(super) fn prepare_for_browser(store: &AgentStore, id: &str) {
    if store.job(id).unwrap().mode != AgentMode::ContentPreparation {
        return;
    }
    let job = store.claim(id, "fixture-generation").unwrap().unwrap();
    let controls = store.controls_get(id).unwrap();
    for (index, product) in job.snapshot.products.iter().enumerate() {
        let skip = controls["items"]
            .as_array()
            .unwrap()
            .iter()
            .any(|i| i["productId"] == product["id"] && i["action"] == "skip");
        let (key, p) = package(
            store,
            &job,
            index,
            if skip { "skipped" } else { "approved" },
        );
        store
            .content_put(
                job.scope.as_ref().unwrap(),
                "fixture-generation",
                product["id"].as_str().unwrap(),
                &key,
                &p,
            )
            .unwrap();
    }
    store
        .mark_step(
            job.scope.as_ref().unwrap(),
            "fixture-generation",
            &output(StepState::Prepared),
        )
        .unwrap();
    store.actor_stopped(id, false).unwrap();
}

#[test]
fn preparation_uses_real_bindings_without_browser_account_or_provider_capacity() {
    let (_temp, store) = fixture();
    let snap = snapshot();
    let (_, browser, _) = create(&store, snap.clone(), Preset::InspectAccounts);
    claim(&store, &browser);
    let (_, id) = raw_listing(&store, snap.clone());
    let capacity = ProviderCapacity {
        max_running: 0,
        running_profiles: vec![snap.profile_id.clone()],
    };
    let job = store
        .claim_with_capacity(&id, "fixture-generation", Some(&capacity))
        .unwrap()
        .unwrap();
    let scope = job.scope.as_ref().unwrap();
    assert_eq!(scope.mode, AgentMode::ContentPreparation);
    assert_eq!(scope.window_id, snap.window_id);
    assert_eq!(scope.account_id, snap.account["accountId"]);
    assert!(!store.has_browser_ownership(&id).unwrap());
    assert_eq!(
        store.retained_window_owners().unwrap(),
        vec![(snap.window_id, browser)]
    );
    assert_eq!(
        store
            .model_acquire(
                scope,
                "fixture-generation",
                &ModelAcquire {
                    request_id: fresh(),
                    kind: "decision".into()
                }
            )
            .unwrap()["acquired"],
        true
    );
    store.control_job(&job.id, ControlAction::Pause).unwrap();
    store.settle_control(&job.id, false).unwrap();
    store.actor_stopped(&job.id, false).unwrap();
    assert!(!store.has_browser_ownership(&job.id).unwrap());
}

#[test]
fn preparation_workers_are_bounded_independently_of_browser_concurrency() {
    let (_temp, store) = fixture();
    let mut jobs = Vec::new();
    for _ in 0..4 {
        let (_, job) = raw_listing(&store, snapshot());
        jobs.push(job);
    }
    for job in &jobs[..3] {
        assert!(store.claim(job, "fixture-generation").unwrap().is_some());
    }
    assert!(
        store
            .claim(&jobs[3], "fixture-generation")
            .unwrap()
            .is_none()
    );
    let (_, browser, _) = create(&store, snapshot(), Preset::InspectAccounts);
    assert!(
        store
            .claim(&browser, "fixture-generation")
            .unwrap()
            .is_some()
    );
}

#[test]
fn preparation_cannot_enter_browser_plugin_or_action_gateways() {
    let (_temp, store) = fixture();
    let (_, id) = raw_listing(&store, snapshot());
    let job = store.claim(&id, "fixture-generation").unwrap().unwrap();
    let scope = job.scope.as_ref().unwrap();
    assert!(
        store
            .action_prepare(
                scope,
                "fixture-generation",
                &fresh(),
                "listing",
                &"a".repeat(64)
            )
            .is_err()
    );
    assert!(store.action_get(scope, &fresh()).is_err());
    assert!(crate::core::agent::execution::require_browser(&job).is_err());
    let (_temp, host, service, caller, scope) =
        gateway_fixture_with_mode(AgentMode::ContentPreparation);
    for (method, payload) in [
        (
            "agent.browser.execute",
            json!({"operation":"snapshot","origin":"https://www.vinted.com","input":{}}),
        ),
        (
            "agent.plugin.call",
            json!({"pluginId":"studio.vinted-accounts","capability":"account.pool",
            "method":"vinted.accounts.agent.snapshot","payload":{"windowId":scope.window_id}}),
        ),
        (
            "agent.action.prepare",
            json!({"operationId":fresh(),"kind":"listing","digest":"a".repeat(64)}),
        ),
        ("agent.action.get", json!({"operationId":fresh()})),
    ] {
        let error = service
            .handle_host(caller.clone(), host_request(&scope, method, payload))
            .unwrap_err();
        assert_eq!(error.code, "PERMISSION_DENIED");
        assert!(error.message.contains("Content preparation"));
    }
    host.shutdown();
}

#[test]
fn prepared_transition_requires_all_durable_outcomes_and_preserves_approvals() {
    let (_temp, store) = fixture();
    let mut snap = snapshot();
    snap.products = vec![product(), product(), product()];
    let (_, id) = raw_listing(&store, snap);
    let job = store.claim(&id, "fixture-generation").unwrap().unwrap();
    let scope = job.scope.as_ref().unwrap();
    store
        .checkpoint(
            scope,
            "fixture-generation",
            "agent.checkpoint.put",
            &json!({
                "threadId":id,"checkpointNs":"","checkpoint":{"v":4,"id":"content-checkpoint",
                    "channel_values":{"value":{"phase":"persist"}}},"metadata":{},"newVersions":{}
            }),
        )
        .unwrap();
    let (key, p) = put(&store, &job, 0, "approved");
    assert!(
        store
            .mark_step(scope, "fixture-generation", &output(StepState::Prepared))
            .is_err()
    );
    put(&store, &job, 1, "review_required");
    put(&store, &job, 2, "failed");
    store
        .mark_step(scope, "fixture-generation", &output(StepState::Prepared))
        .unwrap();
    assert!(store.validate_lease(scope, "fixture-generation").is_err());
    assert!(
        store.claim(&id, "fixture-generation").unwrap().is_none(),
        "Preparation actor still drains"
    );
    store.actor_stopped(&id, false).unwrap();
    let browser = store.claim(&id, "fixture-generation").unwrap().unwrap();
    assert_eq!(browser.mode, AgentMode::Browser);
    assert!(
        store
            .checkpoint(
                browser.scope.as_ref().unwrap(),
                "fixture-generation",
                "agent.checkpoint.get",
                &json!({"threadId":id,"checkpointNs":""})
            )
            .unwrap()
            .is_null()
    );
    assert_eq!(
        store
            .content_get(
                browser.scope.as_ref().unwrap(),
                "fixture-generation",
                p["productId"].as_str().unwrap(),
                &key
            )
            .unwrap()["preparation"],
        p
    );
    let rejected_op = listing_operation(&browser, 1);
    assert!(
        store
            .action_prepare(
                browser.scope.as_ref().unwrap(),
                "fixture-generation",
                &rejected_op,
                "listing",
                &"a".repeat(64)
            )
            .is_err()
    );
    for kind in ["decision", "generation"] {
        assert!(
            store
                .model_acquire(
                    browser.scope.as_ref().unwrap(),
                    "fixture-generation",
                    &ModelAcquire {
                        request_id: fresh(),
                        kind: kind.into()
                    }
                )
                .is_err()
        );
    }
    assert!(
        store
            .model_complete(
                browser.scope.as_ref().unwrap(),
                "fixture-generation",
                &ModelComplete {
                    request_id: fresh(),
                    outcome: "succeeded".into(),
                    elapsed_ms: 1,
                    input_tokens: None,
                    output_tokens: None,
                    status: None
                }
            )
            .is_err()
    );
}

#[test]
fn browser_progress_preserves_negative_preparation_outcomes_and_attention() {
    let (_temp, store) = fixture();
    let mut snap = snapshot();
    snap.products = vec![product(), product(), product()];
    let (_, id) = raw_listing(&store, snap);
    let preparation = store.claim(&id, "fixture-generation").unwrap().unwrap();
    put(&store, &preparation, 0, "approved");
    for (index, state) in [(1, "review_required"), (2, "failed")] {
        let (key, mut receipt) = package(&store, &preparation, index, state);
        receipt["reason"] = json!(format!("Durable {state} reason"));
        store
            .content_put(
                preparation.scope.as_ref().unwrap(),
                "fixture-generation",
                receipt["productId"].as_str().unwrap(),
                &key,
                &receipt,
            )
            .unwrap();
    }
    store
        .mark_step(
            preparation.scope.as_ref().unwrap(),
            "fixture-generation",
            &output(StepState::Prepared),
        )
        .unwrap();
    store.actor_stopped(&id, false).unwrap();
    let browser = store.claim(&id, "fixture-generation").unwrap().unwrap();
    for state in ["pending", "preparing", "skipped"] {
        let mut step = output(StepState::Continue);
        step.item_updates = (1..3)
            .map(|index| ItemUpdate {
                product_id: browser.snapshot.products[index]["id"]
                    .as_str()
                    .unwrap()
                    .into(),
                state: state.into(),
                reason: "Graph advanced past item".into(),
                title: None,
                description: None,
            })
            .collect();
        store
            .mark_step(browser.scope.as_ref().unwrap(), "fixture-generation", &step)
            .unwrap();
    }
    for (index, expected) in [(1, "review_required"), (2, "failed")] {
        let (state, reason): (String, String) = store
            .open()
            .unwrap()
            .query_row(
                "SELECT state,reason FROM agent_items WHERE job_id=?1 AND product_id=?2",
                rusqlite::params![id, browser.snapshot.products[index]["id"].as_str().unwrap()],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(state, expected);
        assert_eq!(reason, format!("Durable {expected} reason"));
    }
    store
        .mark_step(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &output(StepState::Completed),
        )
        .unwrap();
    assert_eq!(store.job(&id).unwrap().state, "review_required");
    assert!(!store.needs_reprepare(&id).unwrap());
}

#[test]
fn missing_preparation_returns_to_preparation_without_localized_message_matching() {
    let (_temp, store) = fixture();
    let (_, id) = raw_listing(&store, snapshot());
    prepare_for_browser(&store, &id);
    let browser = store.claim(&id, "fixture-generation").unwrap().unwrap();
    store.open().unwrap().execute(
        "UPDATE agent_content_receipts SET invalidation_reason='fixture stale content' WHERE job_id=?1",
        [&id]).unwrap();
    let mut step = output(StepState::ReviewRequired);
    step.phase = "halt".into();
    step.message = Some("Approved content is unavailable".into());
    store
        .mark_step(browser.scope.as_ref().unwrap(), "fixture-generation", &step)
        .unwrap();
    assert!(store.needs_reprepare(&id).unwrap());
    assert!(store.has_browser_ownership(&id).unwrap());
    store.actor_stopped(&id, true).unwrap();
    assert_eq!(store.job(&id).unwrap().mode, AgentMode::ContentPreparation);
    assert!(!store.has_browser_ownership(&id).unwrap());
}

