#[test]
fn restart_recovers_preparation_and_transition_drains_without_retained_windows() {
    for transitioned in [false, true] {
        let (temp, store) = fixture();
        let (_, id) = raw_listing(&store, snapshot());
        let job = store.claim(&id, "fixture-generation").unwrap().unwrap();
        let (key, p) = put(&store, &job, 0, "approved");
        if transitioned {
            store
                .mark_step(
                    job.scope.as_ref().unwrap(),
                    "fixture-generation",
                    &output(StepState::Prepared),
                )
                .unwrap();
        }
        drop(store);
        let reopened = AgentStore::new(temp.path().join("nexus.sqlite")).unwrap();
        reopened.recover().unwrap();
        assert!(reopened.retained_window_owners().unwrap().is_empty());
        assert_eq!(reopened.job(&id).unwrap().state, "queued");
        let resumed = reopened.claim(&id, "fixture-generation").unwrap().unwrap();
        assert_eq!(
            reopened
                .content_get(
                    resumed.scope.as_ref().unwrap(),
                    "fixture-generation",
                    p["productId"].as_str().unwrap(),
                    &key
                )
                .unwrap()["preparation"],
            p
        );
        assert!(
            reopened
                .validate_lease(job.scope.as_ref().unwrap(), "fixture-generation")
                .is_err()
        );
    }
}

