#[test]
fn bounded_form_polls_retain_actor_without_consuming_step_budget_or_cooldowns() {
    let (_temp, store) = fixture();
    let (_, id) = raw_listing(&store, snapshot());
    prepare_for_browser(&store, &id);
    let browser = store.claim(&id, "fixture-generation").unwrap().unwrap();
    for _ in 0..100 {
        let mut step = output(StepState::Continue);
        step.retry = Some(StepRetry {
            attempt: 1,
            max_attempts: 1,
            next_attempt_at: crate::core::agent::schema::timestamp(
                &store.open().unwrap(),
                crate::core::agent::now_ms() + 1000,
            )
            .unwrap(),
            code: "WAITING_FOR_FORM".into(),
        });
        store
            .mark_step(browser.scope.as_ref().unwrap(), "fixture-generation", &step)
            .unwrap();
    }
    assert_eq!(store.job(&id).unwrap().steps, browser.steps);
    assert_eq!(store.job(&id).unwrap().state, "running");
    assert!(store.has_browser_ownership(&id).unwrap());
    assert!(!store.queued().unwrap().contains(&id));
    assert!(store.form_wait_until(&id).unwrap() > crate::core::agent::now_ms());
}

