fn reserve(store: &AgentStore, job: &Job, sequence: u64) -> Value {
    let input = json!({"operationId":fresh(),"accountId":job.snapshot.account["accountId"],
        "windowId":job.snapshot.window_id,"bindingRevision":job.snapshot.account["bindingRevision"],
        "domains":["identity","session"]});
    let scope = job.scope.as_ref().unwrap();
    store
        .reserve_observation(scope, "fixture-generation", &input, None)
        .unwrap();
    let mut reply = input.clone();
    reply.as_object_mut().unwrap().remove("domains");
    reply["sequence"] = json!(sequence);
    reply["storageDurable"] = json!(true);
    store
        .reserve_observation(scope, "fixture-generation", &input, Some(&reply))
        .unwrap();
    let mut record = input;
    record.as_object_mut().unwrap().remove("domains");
    record["sequence"] = json!(sequence);
    record["observedAt"] = json!("2026-11-13T01:00:00.000Z");
    record["source"] = json!("official");
    record
}

fn logout_record(mut record: Value) -> Value {
    record["current"] = json!({"status":"logged_out","reason":"current_access_denied",
        "httpStatus":403,"code":106,"messageCode":"access_denied"});
    record
}

fn record(store: &AgentStore, job: &Job, input: &Value) {
    let scope = job.scope.as_ref().unwrap();
    store
        .observation_record_intent(scope, "fixture-generation", input)
        .unwrap();
    store.observation_recorded(scope,"fixture-generation",input,&json!({
        "operationId":input["operationId"],"accountId":input["accountId"],"applied":true,"storageDurable":true
    })).unwrap();
}

#[test]
fn logout_requires_reserved_fenced_exact_current_evidence_and_projects_login_attention() {
    let (_temp, store) = fixture();
    let (batch, id, _) = create(&store, snapshot(), Preset::InspectAccounts);
    let job = claim(&store, &id);
    let input = logout_record(reserve(&store, &job, 1));
    for (field, value) in [
        ("code", json!("106")),
        ("httpStatus", json!(500)),
        ("messageCode", json!("other")),
    ] {
        let mut invalid = input.clone();
        invalid["current"][field] = value;
        assert!(
            store
                .observation_record_intent(
                    job.scope.as_ref().unwrap(),
                    "fixture-generation",
                    &invalid
                )
                .is_err()
        );
    }
    let mut wrong_binding = input.clone();
    wrong_binding["bindingRevision"] = json!(fresh());
    assert!(
        store
            .observation_record_intent(
                job.scope.as_ref().unwrap(),
                "fixture-generation",
                &wrong_binding
            )
            .is_err()
    );
    let mut unreserved = input.clone();
    unreserved["operationId"] = json!(fresh());
    assert!(
        store
            .observation_record_intent(
                job.scope.as_ref().unwrap(),
                "fixture-generation",
                &unreserved
            )
            .is_err()
    );
    record(&store, &job, &input);
    store
        .mark_step(
            job.scope.as_ref().unwrap(),
            "fixture-generation",
            &output(StepState::LoginRequired),
        )
        .unwrap();
    assert_eq!(store.job(&id).unwrap().state, "login_required");
    assert_eq!(store.batch_view(&batch).unwrap()["attention"], 1);
    assert_eq!(
        store.related("attention", "", 1, 20).unwrap()["items"][0]["state"],
        "login_required"
    );
    store.actor_stopped(&id, true).unwrap();
    store.control_job(&id, ControlAction::Resume).unwrap();
    let resumed = claim(&store, &id);
    let mut authenticated = reserve(&store, &resumed, 2);
    authenticated["current"] = json!({"status":"authenticated","reason":"current_user","platformUserId":"42",
        "isAccountBanned":false});
    record(&store, &resumed, &authenticated);
    assert!(!store.job_needs_login(&id).unwrap());
    assert!(store.require_dispatch_writes(&id).is_ok());
}

