#[test]
fn migration_normalizes_facts_once_and_pauses_an_old_unsubmitted_browser_owner() {
    let (temp, store) = fixture();
    let (_, id) = raw_listing(&store, snapshot());
    prepare_for_browser(&store, &id);
    let browser = store.claim(&id, "fixture-generation").unwrap().unwrap();
    let product = browser.snapshot.products[0].clone();
    store.open().unwrap().execute_batch(
        "DELETE FROM agent_execution_migrations;
         UPDATE agent_jobs SET snapshot_json=json_remove(
           json_set(snapshot_json,'$.account.observation',json('{\"bankAccounts\":{\"records\":[]}}')),
           '$.products[0].platformFacts');").unwrap();
    drop(store);
    let reopened = AgentStore::new(temp.path().join("nexus.sqlite")).unwrap();
    reopened.recover().unwrap();
    let migrated = reopened.job(&id).unwrap();
    assert_eq!(migrated.mode, AgentMode::ContentPreparation);
    assert_eq!(migrated.state, "paused");
    assert_eq!(
        migrated.snapshot.products[0]["platformFacts"],
        json!({"vinted":[]})
    );
    assert_eq!(
        migrated.snapshot.products[0]["revision"],
        product["revision"]
    );
    assert_eq!(migrated.snapshot.products[0]["images"], product["images"]);
    assert!(migrated.snapshot.account.get("observation").is_none());
    assert!(reopened.has_browser_ownership(&id).unwrap());
    assert!(reopened.claim(&id, "fixture-generation").unwrap().is_none());
    reopened.actor_stopped(&id, true).unwrap();
    assert!(!reopened.has_browser_ownership(&id).unwrap());
    reopened.control_job(&id, ControlAction::Resume).unwrap();
    drop(reopened);
    let reopened = AgentStore::new(temp.path().join("nexus.sqlite")).unwrap();
    assert_eq!(reopened.job(&id).unwrap().state, "queued");
}

#[test]
fn migration_pauses_unsubmitted_and_preserves_submitted_and_confirmed_journals() {
    let (temp, store) = fixture();
    let (_, unsubmitted) = raw_listing(&store, snapshot());
    let mut submitted_snapshot = snapshot();
    submitted_snapshot.account["platformUserId"] = json!("43");
    submitted_snapshot.account["homepageUrl"] = json!("https://www.vinted.com/member/43");
    submitted_snapshot.products = vec![product(), product()];
    let (_, submitted) = raw_listing(&store, submitted_snapshot);
    prepare_for_browser(&store, &submitted);
    let browser = store
        .claim(&submitted, "fixture-generation")
        .unwrap()
        .unwrap();
    let confirmed = listing_operation(&browser, 0);
    store
        .action_prepare(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &confirmed,
            "listing",
            &"a".repeat(64),
        )
        .unwrap();
    store
        .action_submitting(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &confirmed,
        )
        .unwrap();
    let result = listing_result(&browser, 0);
    let publication = validate_confirmation(&browser, &confirmed, &result)
        .unwrap()
        .unwrap();
    store
        .action_confirm(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &confirmed,
            &result,
            Some(&publication),
        )
        .unwrap();
    let unknown = listing_operation(&browser, 1);
    store
        .action_prepare(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &unknown,
            "listing",
            &"b".repeat(64),
        )
        .unwrap();
    store
        .action_submitting(
            browser.scope.as_ref().unwrap(),
            "fixture-generation",
            &unknown,
        )
        .unwrap();
    let db = store.open().unwrap();
    db.execute_batch(
        "DELETE FROM agent_execution_migrations;
        UPDATE agent_jobs SET scope_json=json_remove(scope_json,'$.mode');",
    )
    .unwrap();
    drop(db);
    drop(store);
    let reopened = AgentStore::new(temp.path().join("nexus.sqlite")).unwrap();
    reopened.recover().unwrap();
    assert_eq!(reopened.job(&unsubmitted).unwrap().state, "paused");
    assert_eq!(
        reopened.job(&unsubmitted).unwrap().mode,
        AgentMode::ContentPreparation
    );
    assert!(reopened.job(&submitted).unwrap().reconcile_only);
    assert!(reopened.has_uncertain(&submitted).unwrap());
    assert_eq!(reopened.due_outbox().unwrap()[0].operation_id, confirmed);
    assert!(
        reopened
            .product_confirmed(&submitted, &browser.snapshot.products[0]["id"])
            .unwrap()
    );
}
